import { Link, useLocation } from 'react-router-dom';

const navItems = [
  { label: 'Dashboard', to: '/dashboard' },
  { label: 'Fundamentals', to: '/fundamentals' },
  { label: 'Subjects', to: '/subjects' },
  { label: 'Topics', to: '/topics' },
  { label: 'Domains', to: '/domains' },
  { label: 'Chatbot', to: '/chatbot' },
  { label: 'Quiz', to: '/quiz' },
  { label: 'Roadmap', to: '/roadmap' },
  { label: 'Tasks', to: '/tasks' },
  { label: 'Progress', to: '/progress' },
];

export default function Sidebar() {
  const location = useLocation();
  return (
    <aside className="hidden w-72 shrink-0 border-r border-slate-800 bg-slate-950 p-5 md:block">
      <div className="space-y-4">
        <div>
          <p className="text-xs uppercase tracking-[0.3em] text-slate-500">Navigation</p>
          <h2 className="mt-3 text-xl font-semibold text-slate-100">Learning Hub</h2>
        </div>
        <div className="space-y-2">
          {navItems.map((item) => {
            const active = location.pathname === item.to;
            return (
              <Link
                key={item.to}
                to={item.to}
                className={`block rounded-2xl px-4 py-3 text-sm font-medium transition ${
                  active
                    ? 'bg-cyan-500/15 text-cyan-300 shadow-inner shadow-cyan-500/10'
                    : 'text-slate-300 hover:bg-slate-800 hover:text-white'
                }`}
              >
                {item.label}
              </Link>
            );
          })}
        </div>
      </div>
    </aside>
  );
}
